public class MemoryDemo {
    public static void main(String[] args) {
        int age = 25;                       // Primitive on Stack
        User user = new User("Alice", 100);  // Reference on Stack -> Object on Heap
        updateUser(user, 50);
        user = null;                        // Pointer cleared -> Heap object becomes GC candidate!
    }

    static void updateUser(User u, int bonus) {
        u.setScore(u.getScore() + bonus);   // Mutates Heap object at @0x5F3A
    }
}
